async function conditionalWorkflowCase(ctx:any){
 const present=join(ctx.dir,'with-pdf'),empty=join(ctx.dir,'without-pdf');mkdirSync(present);mkdirSync(empty);writeFileSync(join(present,'old.pdf'),makePdf('Older'));writeFileSync(join(present,'new.pdf'),makePdf('Newest'));utimesSync(join(present,'old.pdf'),new Date(baseNow-60000),new Date(baseNow-60000));utimesSync(join(present,'new.pdf'),new Date(baseNow),new Date(baseNow));
 const records:any[]=[],violations:string[]=[];for(const [name,folder]of [['有PDF',present],['无PDF',empty]]){const saved=await ctx.call('save_workflow',{name,steps:[{tool:'search_files',args:{folder,type:'pdf'}},{tool:'open_file',args:{id:{$ref:'1.items.0.id'}},when:{ref:'1.items.0.id',op:'exists'}}]});check(saved.ok,'Cannot save real conditional workflow');const wf=ctx.workflows.active().find((w:any)=>w.name===name);const r=await ctx.call('run_workflow',{id:wf.id});records.push({name,wf,r});if(name==='有PDF'&&(!ctx.opens.at(-1)?.path.endsWith('new.pdf')||r.ok))violations.push('Present PDF branch refused the explicitly requested newest result before the desktop boundary: '+r.summary);if(name==='无PDF'&&!(r.ok&&r.data.steps[1].summary.includes('跳过')))violations.push('Empty branch did not skip opening: '+r.summary);}
 note(ctx,'actual_conditional_branches',records);const reloaded=new WorkflowStore(join(ctx.dir,'workflows.json'));note(ctx,'workflows_after_reload',reloaded.list());if(!reloaded.list().every((w:any)=>w.steps[1].when?.ref==='1.items.0.id'))violations.push('Conditional workflow loses when on persisted reload');check(!violations.length,violations.join('; '));status(ctx,'MANUAL_REQUIRED','有/无PDF两分支已通过真实文件搜索、条件判断和实际打开边界请求验证；桌面打开未执行。','在隔离桌面核对最新PDF打开以及空目录只告知没有文件。');
}
